var ImportedPlaneAPISerializersAssetGenericassetuploadserializerRequestRequest = Type("PlaneApiSerializersAssetGenericassetuploadserializerRequestRequest", func() {
	Meta("openapi:typename:canonical", "true")
	Description("Serializer for generic asset upload requests with project association.\n\nValidates metadata for generating presigned URLs for workspace assets including\nproject association, external system tracking, and file validation for\ndocument management and content storage workflows.")
	Attribute("external_id", String, func() {
		MinLength(1)
	})
	Attribute("external_source", String, func() {
		MinLength(1)
	})
	Attribute("name", String, func() {
		MinLength(1)
	})
	Attribute("project_id", String, func() {
		Format(FormatUUID)
	})
	Attribute("size", Int, func() {
		Meta("openapi:format", "")
	})
	Attribute("type", String, func() {
		MinLength(1)
	})
	Required("name", "size")
})

var ImportedPlaneAPISerializersAssetUserassetuploadserializerRequestRequest = Type("PlaneApiSerializersAssetUserassetuploadserializerRequestRequest", func() {
	Meta("openapi:typename:canonical", "true")
	Description("Serializer for user asset upload requests.\n\nThis serializer validates the metadata required to generate a presigned URL\nfor uploading user profile assets (avatar or cover image) directly to S3 storage.\nSupports JPEG, PNG, WebP, JPG, and GIF image formats with size validation.")
	Attribute("entity_type", ImportedEntityTypeEnum, func() {
		Meta("openapi:allOf:reference", "true")
	})
	Attribute("name", String, func() {
		MinLength(1)
	})
	Attribute("size", Int, func() {
		Meta("openapi:format", "")
	})
	Attribute("type", ImportedPlaneAPISerializersAssetUserassetuploadserializerRequestTypeEnum, func() {
		Meta("openapi:allOf:reference", "true")
		Default("image/jpeg")
	})
	Required("entity_type", "name", "size")
})

var ImportedPlaneAPISerializersAssetUserassetuploadserializerRequestTypeEnum = Type("PlaneApiSerializersAssetUserassetuploadserializerRequestTypeEnum", String, func() {
	Meta("openapi:typename:canonical", "true")
	Description("* `image/jpeg` - JPEG\n* `image/png` - PNG\n* `image/webp` - WebP\n* `image/jpg` - JPG\n* `image/gif` - GIF")
	Enum("image/jpeg", "image/png", "image/webp", "image/jpg", "image/gif")
})

